const dictionaries:Record<string,Dictionary>={en};
for(const [locale,value] of Object.entries(raw)){
  const values=value.split('|');
  if(values.length!==commonKeys.length)throw new Error(`Translation count for ${locale}: ${values.length}, expected ${commonKeys.length}`);
  dictionaries[locale]=Object.fromEntries(commonKeys.map((k,i)=>[k,values[i]])) as Dictionary;
}
const stories:Record<string,string[]>={
 'zh-TW':['小小篇幅。\n大大心動。','走進全新世界，探索來自各地創作者的精彩短劇。','人類的故事，無限的想像。','真人、動畫，或只有 AI 能想像的世界。每位創作者都屬於這裡。','每個好故事，\n都從創作者開始。','用你的語言創作短劇，與全球觀眾相遇，從每次解鎖獲得收益。歡迎真人與 AI 創作者。','一次支付 HK$88，無須每月訂閱。','每集最多 3 分鐘、75 MB，包含 5 GB 儲存空間。','選擇免費集數，每集收費由 US$0.10 起。你獲得每次解鎖收入的 70%。','示範付款：不會扣除或支付真實款項。','登入以收藏劇集，並解鎖更多精彩內容。','錢包以美元計價，已解鎖集數可重複觀看。'],
 'zh-CN':['小小篇幅。\n大大心动。','走进全新世界，探索来自各地创作者的精彩短剧。','人类的故事，无限的想象。','真人、动画，或只有 AI 能想象的世界。每位创作者都属于这里。','每个好故事，\n都从创作者开始。','用你的语言创作短剧，与全球观众相遇，从每次解锁获得收益。欢迎真人与 AI 创作者。','一次支付 HK$88，无须每月订阅。','每集最多 3 分钟、75 MB，包含 5 GB 存储空间。','选择免费集数，每集收费由 US$0.10 起。你获得每次解锁收入的 70%。','演示付款：不会扣除或支付真实款项。','登录以收藏剧集，并解锁更多精彩内容。','钱包以美元计价，已解锁集数可重复观看。'],
 ja:['短い物語。\n大きなときめき。','世界中のクリエイターが贈る、新しいショートドラマに出会おう。','人の物語。無限の想像力。','実写もアニメもAI作品も。すべての語り手を歓迎します。','素晴らしい物語は、\nあなたから始まる。','あなたの言語で作品を届け、世界の視聴者とつながり、エピソード販売で収益を。','HK$88の初回料金のみ。月額料金なし。','1話3分・75 MBまで。ストレージ5 GB付き。','無料エピソード数を選び、有料分はUS$0.10から。売上の70%を受け取れます。','テスト決済です。実際の請求や送金はありません。','ログインして作品を保存し、新しいエピソードを楽しもう。','残高は米ドル建て。購入したエピソードは繰り返し視聴できます。'],
 ko:['짧은 에피소드.\n커다란 설렘.','전 세계 크리에이터가 만든 특별한 숏드라마를 만나보세요.','사람의 이야기. 무한한 상상력.','실사, 애니메이션, AI 작품까지. 모든 이야기꾼을 환영합니다.','멋진 이야기는\n당신에게서 시작됩니다.','당신의 언어로 작품을 만들고 세계 시청자를 만나 수익을 얻으세요.','HK$88 한 번 결제. 월 구독료가 없습니다.','에피소드당 최대 3분, 75 MB. 저장 공간 5 GB 포함.','무료 에피소드 수를 정하고 유료 편은 US$0.10부터 판매하세요. 판매액의 70%가 창작자 몫입니다.','테스트 결제입니다. 실제 결제나 지급은 발생하지 않습니다.','로그인해 이야기를 저장하고 더 많은 에피소드를 즐기세요.','지갑 잔액은 USD 기준이며 구매한 에피소드는 계속 볼 수 있습니다.'],
 hi:['छोटे एपिसोड।\nबड़े एहसास।','दुनियाभर के क्रिएटर्स की बेहतरीन छोटी कहानियाँ खोजें।','इंसानी कहानियाँ। असीम कल्पना।','लाइव एक्शन, एनिमेशन या AI—हर कहानीकार का स्वागत है।','हर शानदार कहानी\nएक क्रिएटर से शुरू होती है।','अपनी भाषा में बनाएँ, दुनिया तक पहुँचें और हर अनलॉक पर कमाएँ।','एक बार HK$88। कोई मासिक सदस्यता नहीं।','हर एपिसोड अधिकतम 3 मिनट और 75 MB। 5 GB स्टोरेज शामिल।','मुफ़्त एपिसोड चुनें। भुगतान एपिसोड US$0.10 से। बिक्री का 70% आपका।','परीक्षण भुगतान। कोई असली पैसा लिया या दिया नहीं जाएगा।','कहानियाँ सहेजने और अधिक एपिसोड खोलने के लिए लॉग इन करें।','वॉलेट USD में है। अनलॉक किए एपिसोड फिर से देख सकते हैं।'],
 id:['Episode singkat.\nPerasaan besar.','Temukan drama pendek luar biasa dari kreator di seluruh dunia.','Cerita manusia. Imajinasi tanpa batas.','Live action, animasi, atau AI. Semua pencerita diterima di sini.','Setiap cerita hebat\nberawal dari seorang kreator.','Berkarya dalam bahasa Anda, temukan penonton global, dan dapatkan penghasilan.','HK$88 sekali bayar. Tanpa langganan bulanan.','Maksimal 3 menit dan 75 MB per episode. Penyimpanan 5 GB termasuk.','Pilih episode gratis. Episode berbayar mulai US$0.10. Anda menerima 70% penjualan.','Pembayaran uji coba. Tidak ada uang sungguhan yang ditagih atau dibayarkan.','Masuk untuk menyimpan cerita dan membuka episode lainnya.','Saldo dalam USD. Episode yang dibuka dapat ditonton kembali.'],
 'pt-BR':['Episódios curtos.\nGrandes emoções.','Descubra dramas curtos extraordinários de criadores do mundo inteiro.','Histórias humanas. Imaginação sem limites.','Live action, animação ou IA. Todo contador de histórias é bem-vindo.','Toda grande história\ncomeça com um criador.','Crie no seu idioma, encontre um público global e ganhe com cada episódio.','HK$88 uma única vez. Sem mensalidade.','Até 3 minutos e 75 MB por episódio. Inclui 5 GB de armazenamento.','Escolha episódios grátis. Episódios pagos a partir de US$0.10. Você recebe 70% das vendas.','Pagamento de teste. Nenhum dinheiro real será cobrado ou pago.','Entre para salvar histórias e desbloquear mais episódios.','Saldo em USD. Episódios desbloqueados continuam disponíveis.'],
 es:['Episodios cortos.\nGrandes emociones.','Descubre historias extraordinarias de creadores de todo el mundo.','Historias humanas. Imaginación sin límites.','Acción real, animación o IA. Todos los creadores son bienvenidos.','Toda gran historia\nempieza con un creador.','Crea en tu idioma, llega al mundo y gana con cada episodio desbloqueado.','HK$88 una sola vez. Sin suscripción mensual.','Hasta 3 minutos y 75 MB por episodio. Incluye 5 GB de almacenamiento.','Elige episodios gratis. Episodios de pago desde US$0.10. Recibes el 70% de las ventas.','Pago de prueba. No se cobrará ni pagará dinero real.','Inicia sesión para guardar historias y desbloquear más episodios.','Saldo en USD. Los episodios desbloqueados siguen disponibles.'],
 ar:['حلقات قصيرة.\nمشاعر كبيرة.','اكتشف قصصًا استثنائية من مبدعين حول العالم.','قصص إنسانية. خيال بلا حدود.','تمثيل حي أو رسوم أو ذكاء اصطناعي. نرحب بكل صانع قصص.','كل قصة رائعة\nتبدأ بمبدع.','انشر بلغتك وتواصل مع جمهور عالمي واربح من كل حلقة مدفوعة.','HK$88 لمرة واحدة. بدون اشتراك شهري.','حتى 3 دقائق و75 MB للحلقة. مساحة 5 GB مشمولة.','حدد الحلقات المجانية. الحلقات المدفوعة من US$0.10. تحصل على 70% من المبيعات.','دفع تجريبي. لن يتم تحصيل أو دفع أموال حقيقية.','سجل الدخول لحفظ القصص وفتح المزيد من الحلقات.','الرصيد بالدولار الأمريكي. الحلقات المفتوحة متاحة لإعادة المشاهدة.'],
 bn:['ছোট পর্ব।\nবড় অনুভূতি।','বিশ্বের স্রষ্টাদের অসাধারণ ছোট নাটক আবিষ্কার করুন।','মানুষের গল্প। সীমাহীন কল্পনা।','লাইভ অ্যাকশন, অ্যানিমেশন বা AI। সব গল্পকারকে স্বাগত।','প্রতিটি দুর্দান্ত গল্প\nএকজন স্রষ্টা দিয়ে শুরু।','নিজের ভাষায় তৈরি করুন, বিশ্বজুড়ে দর্শক পান এবং আয় করুন।','একবার HK$88। মাসিক সাবস্ক্রিপশন নেই।','প্রতি পর্ব সর্বোচ্চ 3 মিনিট ও 75 MB। 5 GB স্টোরেজসহ।','ফ্রি পর্ব বেছে নিন। পেইড পর্ব US$0.10 থেকে। বিক্রির 70% আপনার।','পরীক্ষামূলক পেমেন্ট। প্রকৃত অর্থ নেওয়া বা দেওয়া হবে না।','গল্প সংরক্ষণ ও পর্ব আনলক করতে লগ ইন করুন।','ওয়ালেট USD-তে। আনলক করা পর্ব আবার দেখতে পারবেন।'],
 ur:['چھوٹی اقساط۔\nبڑے احساسات۔','دنیا بھر کے تخلیق کاروں کی شاندار مختصر کہانیاں دیکھیں۔','انسانی کہانیاں۔ لامحدود تخیل۔','لائیو ایکشن، اینیمیشن یا AI۔ ہر کہانی کار کا استقبال ہے۔','ہر اچھی کہانی\nایک تخلیق کار سے شروع ہوتی ہے۔','اپنی زبان میں بنائیں، عالمی ناظرین پائیں اور کمائیں۔','ایک بار HK$88۔ کوئی ماہانہ سبسکرپشن نہیں۔','ہر قسط زیادہ سے زیادہ 3 منٹ اور 75 MB۔ 5 GB اسٹوریج شامل۔','مفت اقساط چنیں۔ ادا شدہ اقساط US$0.10 سے۔ 70% فروخت آپ کی۔','آزمائشی ادائیگی۔ کوئی حقیقی رقم وصول یا ادا نہیں ہوگی۔','کہانیاں محفوظ اور اقساط کھولنے کے لیے لاگ ان کریں۔','بیلنس USD میں ہے۔ کھولی گئی اقساط دوبارہ دیکھ سکتے ہیں۔'],
 vi:['Tập phim ngắn.\nCảm xúc lớn.','Khám phá phim ngắn đặc sắc từ các nhà sáng tạo khắp thế giới.','Câu chuyện con người. Trí tưởng tượng vô hạn.','Người thật, hoạt hình hay AI. Mọi nhà sáng tạo đều được chào đón.','Mọi câu chuyện hay\nđều bắt đầu từ người sáng tạo.','Sáng tạo bằng ngôn ngữ của bạn, tiếp cận khán giả toàn cầu và kiếm thu nhập.','HK$88 một lần. Không phí thuê bao tháng.','Tối đa 3 phút và 75 MB mỗi tập. Bao gồm 5 GB lưu trữ.','Chọn tập miễn phí. Tập trả phí từ US$0.10. Bạn nhận 70% doanh thu.','Thanh toán thử nghiệm. Không thu hoặc trả tiền thật.','Đăng nhập để lưu phim và mở khóa thêm tập.','Số dư bằng USD. Tập đã mở khóa có thể xem lại.'],
 th:['ตอนสั้น ๆ\nความรู้สึกยิ่งใหญ่','ค้นพบละครสั้นจากครีเอเตอร์ทั่วโลก','เรื่องราวของผู้คน จินตนาการไร้ขีดจำกัด','คนแสดง แอนิเมชัน หรือ AI ยินดีต้อนรับนักเล่าเรื่องทุกคน','ทุกเรื่องราวที่ยอดเยี่ยม\nเริ่มต้นจากผู้สร้าง','สร้างในภาษาของคุณ เข้าถึงผู้ชมทั่วโลก และสร้างรายได้','HK$88 ครั้งเดียว ไม่มีค่าสมาชิกรายเดือน','แต่ละตอนไม่เกิน 3 นาทีและ 75 MB รวมพื้นที่ 5 GB','เลือกตอนฟรี ตอนชำระเงินเริ่ม US$0.10 คุณได้รับ 70% ของยอดขาย','การชำระเงินทดสอบ ไม่มีการเก็บหรือจ่ายเงินจริง','เข้าสู่ระบบเพื่อบันทึกเรื่องราวและปลดล็อกตอนเพิ่มเติม','ยอดเงินเป็น USD ตอนที่ปลดล็อกแล้วสามารถดูซ้ำได้'],
 fil:['Maiikling episode.\nMalalaking damdamin.','Tuklasin ang mga pambihirang kuwento mula sa mga creator sa buong mundo.','Kuwentong pantao. Walang-hanggang imahinasyon.','Live action, animation o AI. Lahat ng storyteller ay welcome.','Bawat mahusay na kuwento\nay nagsisimula sa isang creator.','Gumawa sa iyong wika, abutin ang mundo, at kumita sa bawat unlock.','Isang beses na HK$88. Walang buwanang subscription.','Hanggang 3 minuto at 75 MB bawat episode. Kasama ang 5 GB storage.','Pumili ng libreng episode. Bayad na episode mula US$0.10. Sa iyo ang 70% ng benta.','Test payment. Walang totoong perang sisingilin o ibabayad.','Mag-sign in para mag-save at mag-unlock ng mga episode.','Nasa USD ang balanse. Mapapanood muli ang na-unlock na episode.'],
 tr:['Kısa bölümler.\nBüyük duygular.','Dünyanın dört bir yanındaki yaratıcılardan olağanüstü kısa diziler keşfet.','İnsan hikâyeleri. Sınırsız hayal gücü.','Canlı çekim, animasyon veya AI. Her hikâye anlatıcısına yer var.','Her harika hikâye\nbir yaratıcıyla başlar.','Kendi dilinde üret, dünyaya ulaş ve her bölüm satışından kazan.','Tek seferlik HK$88. Aylık abonelik yok.','Bölüm başına en fazla 3 dakika ve 75 MB. 5 GB depolama dahil.','Ücretsiz bölümleri seç. Ücretli bölümler US$0.10’dan başlar. Satışın %70’i senin.','Test ödemesi. Gerçek para alınmaz veya ödenmez.','Hikâyeleri kaydetmek ve bölümleri açmak için giriş yap.','Bakiye USD cinsindedir. Açılan bölümler tekrar izlenebilir.'],
 ru:['Короткие серии.\nБольшие чувства.','Откройте необычные истории от авторов со всего мира.','Истории людей. Безграничное воображение.','Живые актёры, анимация или ИИ. Здесь рады каждому автору.','Каждая большая история\nначинается с автора.','Создавайте на своём языке, находите зрителей по всему миру и зарабатывайте.','HK$88 один раз. Без ежемесячной подписки.','До 3 минут и 75 MB на эпизод. Включено 5 GB хранилища.','Выбирайте бесплатные эпизоды. Платные — от US$0.10. Вам достаётся 70% продаж.','Тестовый платёж. Реальные деньги не списываются и не выплачиваются.','Войдите, чтобы сохранять истории и открывать эпизоды.','Баланс в USD. Купленные эпизоды можно пересматривать.'],
 fr:['Petits épisodes.\nGrandes émotions.','Découvrez des histoires extraordinaires de créateurs du monde entier.','Des histoires humaines. Une imagination sans limites.','Prise de vue réelle, animation ou IA. Tous les créateurs sont les bienvenus.','Chaque grande histoire\ncommence par un créateur.','Créez dans votre langue, trouvez votre public et gagnez sur chaque épisode.','HK$88 une seule fois. Sans abonnement mensuel.','3 minutes et 75 MB maximum par épisode. 5 GB de stockage inclus.','Choisissez les épisodes gratuits. Épisodes payants dès US$0.10. Vous recevez 70% des ventes.','Paiement de test. Aucun argent réel ne sera débité ni versé.','Connectez-vous pour enregistrer et débloquer des épisodes.','Solde en USD. Les épisodes débloqués restent accessibles.'],
 de:['Kurze Folgen.\nGroße Gefühle.','Entdecke außergewöhnliche Geschichten von Kreativen aus aller Welt.','Menschliche Geschichten. Grenzenlose Fantasie.','Realfilm, Animation oder KI. Alle Geschichtenerzähler sind willkommen.','Jede große Geschichte\nbeginnt mit einem kreativen Kopf.','Erstelle in deiner Sprache, finde ein weltweites Publikum und verdiene mit jeder Folge.','Einmalig HK$88. Kein monatliches Abo.','Höchstens 3 Minuten und 75 MB pro Folge. 5 GB Speicher inklusive.','Wähle kostenlose Folgen. Bezahlfolgen ab US$0.10. Du erhältst 70% des Umsatzes.','Testzahlung. Es wird kein echtes Geld berechnet oder ausgezahlt.','Melde dich an, um Geschichten zu speichern und Folgen freizuschalten.','Guthaben in USD. Freigeschaltete Folgen bleiben verfügbar.'],
 ms:['Episod pendek.\nEmosi besar.','Temui drama pendek luar biasa daripada pencipta seluruh dunia.','Cerita manusia. Imaginasi tanpa batas.','Aksi langsung, animasi atau AI. Semua pencerita dialu-alukan.','Setiap cerita hebat\nbermula dengan pencipta.','Berkarya dalam bahasa anda, temui penonton global dan jana pendapatan.','HK$88 sekali sahaja. Tiada langganan bulanan.','Maksimum 3 minit dan 75 MB setiap episod. Storan 5 GB termasuk.','Pilih episod percuma. Episod berbayar dari US$0.10. Anda menerima 70% jualan.','Bayaran ujian. Tiada wang sebenar dicaj atau dibayar.','Log masuk untuk menyimpan cerita dan membuka episod lain.','Baki dalam USD. Episod yang dibuka boleh ditonton semula.'],
 ta:['சிறிய அத்தியாயங்கள்.\nபெரிய உணர்வுகள்.','உலகெங்குமுள்ள படைப்பாளர்களின் சிறந்த குறுநாடகங்களைக் கண்டறியுங்கள்.','மனிதக் கதைகள். எல்லையற்ற கற்பனை.','நேரடி நடிப்பு, அனிமேஷன் அல்லது AI. அனைவருக்கும் இடமுண்டு.','ஒவ்வொரு சிறந்த கதையும்\nஒரு படைப்பாளரிடம் தொடங்குகிறது.','உங்கள் மொழியில் உருவாக்கி உலகளாவிய பார்வையாளர்களை அடைந்து வருவாய் ஈட்டுங்கள்.','ஒருமுறை HK$88. மாதச் சந்தா இல்லை.','ஒரு அத்தியாயம் அதிகபட்சம் 3 நிமிடம், 75 MB. 5 GB சேமிப்பிடம் உண்டு.','இலவச அத்தியாயங்களைத் தேர்வு செய்க. கட்டணப் பகுதிகள் US$0.10 முதல். விற்பனையில் 70% உங்களுக்கு.','சோதனைக் கட்டணம். உண்மைப் பணம் வசூலிக்கப்படாது அல்லது செலுத்தப்படாது.','கதைகளைச் சேமிக்கவும் அத்தியாயங்களைத் திறக்கவும் உள்நுழையுங்கள்.','இருப்பு USD-ல் உள்ளது. திறந்த அத்தியாயங்களை மீண்டும் பார்க்கலாம்.'],
};
